    module alu (
    input wire clk,
    input wire rst,
    input wire [15:0] a,
    input wire [15:0] b,
    input wire [3:0] opcode,
    output reg [15:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Internal signals for combinational logic
    reg [15:0] temp_result;
    reg temp_overflow;
    wire [16:0] add_result;  // Extra bit for overflow detection
    wire [16:0] sub_result;  // Extra bit for overflow detection

    // Compute addition and subtraction with extended precision for overflow
    assign add_result = {1'b0, a} + {1'b0, b};
    assign sub_result = {1'b0, a} - {1'b0, b};

    // Combinational logic for operations
    always @(*) begin
        temp_overflow = 1'b0;
        case (opcode)
            4'b0000: begin // ADD: A + B
                temp_result = add_result[15:0];
                // Overflow occurs when signs are same but result sign differs
                temp_overflow = (a[15] == b[15]) && (temp_result[15] != a[15]);
            end
            
            4'b0001: begin // SUB: A - B
                temp_result = sub_result[15:0];
                // Overflow occurs when signs differ and result sign equals b sign
                temp_overflow = (a[15] != b[15]) && (temp_result[15] == b[15]);
            end
            
            4'b0010: begin // AND: A & B
                temp_result = a & b;
                temp_overflow = 1'b0;  // Bitwise ops don't overflow
            end
            
            4'b0011: begin // OR: A | B
                temp_result = a | b;
                temp_overflow = 1'b0;  // Bitwise ops don't overflow
            end
            
            default: begin // Default to addition for undefined opcodes
                temp_result = add_result[15:0];
                temp_overflow = (a[15] == b[15]) && (temp_result[15] != a[15]);
            end
        endcase
    end

    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result <= 16'b0;
            zero <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result <= temp_result;
            zero <= (temp_result == 16'b0);
            overflow <= temp_overflow;
            negative <= temp_result[15];
        end
    end

endmodule